const {app,BrowserWindow}=require('electron');const fs=require('node:fs');const autoOther=process.argv[4]==='other-radio';const wrongRadio=process.argv[4]==='wrong-radio';const autoSubmit=process.argv[4]==='auto-submit';
app.commandLine.appendSwitch('force-renderer-accessibility');app.disableHardwareAcceleration();
app.whenReady().then(async()=>{
 const win=new BrowserWindow({width:420,height:500,x:12000,y:12000,show:false,focusable:false,webPreferences:{nodeIntegration:false,contextIsolation:true}});
 win.webContents.on('console-message',(_event,_level,message)=>{if(message.startsWith('FIXTURE_SENT:'))fs.writeFileSync(process.argv[2],message.slice(13));});
 const html=`<!doctype html><html><head><title>Conversation fictive</title></head><body><div role="group" id="question"><span>Question</span><p>Quel choix ?</p><div role="radiogroup"><label><input type="radio" name="answer" value="Premier">Premier</label><label><input type="radio" name="answer" value="Deuxième">Deuxième</label>${autoOther?'<label><input type="radio" name="answer" value="Autre">Autre</label>':''}</div><textarea aria-label="Réponse"></textarea><button id="send" disabled>Envoyer</button></div><script>const send=document.getElementById('send');document.querySelector('textarea').value=${JSON.stringify(process.argv[3]||'')};document.addEventListener('input',(e)=>{if(${autoSubmit}&&e.target.type==='radio'){console.log('FIXTURE_SENT:'+e.target.value);document.getElementById('question').remove();return;}if(${autoOther}&&e.target.tagName==='TEXTAREA')document.querySelector('input[value=Autre]').checked=true;if(${wrongRadio}&&e.target.tagName==='TEXTAREA')document.querySelector('input[value=Premier]').checked=true;send.disabled=!document.querySelector('input:checked')&&!document.querySelector('textarea').value});send.disabled=!document.querySelector('textarea').value;send.onclick=()=>{const picked=document.querySelector('input:checked')?.value;const value=picked==='Autre'?document.querySelector('textarea').value:(picked||document.querySelector('textarea').value);console.log('FIXTURE_SENT:'+value);document.getElementById('question').remove()};</script></body></html>`;
 await win.loadURL('data:text/html;charset=utf-8,'+encodeURIComponent(html));win.showInactive();
}).catch(()=>{process.exitCode=1;app.quit();});
